INSERT INTO public.contract_clause_templates (id, title, content, category, order_index, is_active, created_at, updated_at) VALUES ('b8b3d4c8-a6e7-4724-a26b-24c3f8c4f517', 'المادة الأولى: التمهيد وأهدافه', 'يعتبر التمهيد السابق جزءاً لا يتجزأ من هذا العقد ويقرأ ويفسر معه.', 'general', 0, true, '2026-07-15T05:25:45.108437+00:00', '2026-07-15T05:25:45.108437+00:00');
