INSERT INTO public.contract_clause_templates (id, title, content, category, order_index, is_active, created_at, updated_at) VALUES ('8347f687-43b4-47ea-ae8c-7937c731a48d', 'المادة الثالثة: مدة التنفيذ والتسليم', 'يلتزم الطرف الثاني بإنهاء كافة الأعمال المسندة إليه في هذا العقد خلال مدة أقصاها 90 يوماً من تاريخ استلام الموقع.', 'technical', 2, true, '2026-07-15T05:25:45.108437+00:00', '2026-07-15T05:25:45.108437+00:00');
INSERT INTO public.contract_clause_templates (id, title, content, category, order_index, is_active, created_at, updated_at) VALUES ('5453b5bd-2120-4a46-a0f5-6afe76063bb6', 'المادة الرابعة: شروط ومواعيد الدفع', 'تلتزم الطرف الأول بدفع مستحقات الطرف الثاني وفقاً لنظام الدفعات المتفق عليه في ملخص شروط الدفع بنسب الإنجاز.', 'financial', 3, true, '2026-07-15T05:25:45.108437+00:00', '2026-07-15T05:25:45.108437+00:00');
